// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != c.owner() && caller != address(c) && caller != address(0));
        address prevOwner = c.owner();
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
        if (ok) {
            assertTrue(c.owner() == prevOwner);
        } else {
            assertTrue(c.owner() == prevOwner);
        }
    }
}
